/* Recorded impacts from the user-supplied BILLIARDS SOUND EFFECT IN HIGH QUALITY.mp3.
 * Mono PCM16 LE, 32 kHz. Trimmed at onset, high-passed at 85 Hz, gently warmed,
 * peak-normalized to -2.5 dBFS. Natural decays retained with 140 ms cosine tails.
 * Source SHA256: 51c57d10ad92c4f4dbf7f296b67ef083894a8eaa94d771673d39b39fab2ecd73
 * Source peaks (s): ball soft 6.295 / medium 8.470 / hard 14.345; cue 3.120.
 */
function createBilliardsSamples(ac) {
  const pcm = {
    ball: [
      '',
      '',
      ''
    ],
    cue: [
      ''
    ],
  };
  const result = {};
  for (const name of Object.keys(pcm)) {
    result[name] = pcm[name].map(encoded => {
      const bytes = atob(encoded), b = ac.createBuffer(1, bytes.length / 2, 32000), d = b.getChannelData(0);
      for (let i = 0; i < d.length; i++) {
        const v = bytes.charCodeAt(i * 2) | (bytes.charCodeAt(i * 2 + 1) << 8);
        d[i] = (v >= 32768 ? v - 65536 : v) / 32768;
      }
      return b;
    });
  }
  return result;
}
